package main

import (
	"errors"
	"fmt"
)

var ErrOutOfStock = errors.New("out of stock")

var stock = map[string]int{"apple": 5, "pear": 2}

func reserve(item string, qty int) error {
	n, ok := stock[item]
	if !ok {
		return fmt.Errorf("reserve %s: unknown item", item)
	}
	if qty > n {
		return fmt.Errorf("reserve %s: %w", item, ErrOutOfStock)
	}
	stock[item] = n - qty
	return nil
}

func main() {
	var item string
	var qty int
	for {
		if _, err := fmt.Scan(&item, &qty); err != nil {
			break
		}
		if err := reserve(item, qty); err != nil {
			fmt.Println("error:", err)
			fmt.Println("  out of stock:", errors.Is(err, ErrOutOfStock))
			fmt.Println("  unwrapped:", errors.Unwrap(err))
			continue
		}
		fmt.Println("ok")
	}
}

steps.body:
`errors.New` gives you only a message. When callers need details, define your own type. Any type with an `Error() string` method is an `error`:

```go
type RangeError struct {
	Value int
	Min   int
	Max   int
}

func (e *RangeError) Error() string {
	return fmt.Sprintf("%d is outside %d to %d", e.Value, e.Min, e.Max)
}
fmt.Println(&RangeError{Value: 200, Min: 0, Max: 150}) // 200 is outside 0 to 150
```

With a pointer receiver, `*RangeError` is the error type, so return `&RangeError{...}`. The struct escapes to the heap and the `error` holds a pointer to it.

To get the details back out of a wrapped chain, declare a variable of the error type, here `*RangeError`, and pass its address to `errors.As`. If it finds a match, it stores it in your variable and returns true:

```go harness
package main

import (
	"errors"
	"fmt"
)

type RangeError struct {
	Value int
	Min   int
	Max   int
}

func (e *RangeError) Error() string {
	return fmt.Sprintf("%d is outside %d to %d", e.Value, e.Min, e.Max)
}

func main() {
	err := fmt.Errorf("register: %w", &RangeError{Value: 200, Min: 0, Max: 150})
	{{code}}
}
```

```go
var re *RangeError
if errors.As(err, &re) {
	fmt.Println(re.Value)
}
```

Pass `&re`, not `re`. Without the `&`, `errors.As` panics.

Gotcha: on success, return a literal `nil`. If a function returns a `*RangeError` variable that happens to be nil as an `error`, the interface holds a type plus a nil pointer, so `err != nil` is true.

example.code:
package main

import (
	"errors"
	"fmt"
)

type RangeError struct {
	Value int
	Min   int
	Max   int
}

func (e *RangeError) Error() string {
	return fmt.Sprintf("%d is outside %d to %d", e.Value, e.Min, e.Max)
}

func validateAge(age int) error {
	if age < 0 || age > 150 {
		return &RangeError{Value: age, Min: 0, Max: 150}
	}
	return nil
}

func register(age int) error {
	if err := validateAge(age); err != nil {
		return fmt.Errorf("register: %w", err)
	}
	return nil
}

func main() {
	var age int
	for {
		if _, err := fmt.Scan(&age); err != nil {
			break
		}
		err := register(age)
		if err != nil {
			fmt.Println("error:", err)
			var re *RangeError
			if errors.As(err, &re) {
				fmt.Println("  bad value:", re.Value)
			}
			continue
		}
		fmt.Println(age, "ok")
	}
}

