package main

import (
	"errors"
	"fmt"
	"strings"
)

type SettingError struct {
	Index int
	Msg   string
}

func (e *SettingError) Error() string {
	return fmt.Sprintf("setting %d: %s", e.Index, e.Msg)
}

func parseSetting(i int, s string) (string, string, error) {
	parts := strings.Split(s, "=")
	if len(parts) != 2 {
		return "", "", &SettingError{Index: i, Msg: fmt.Sprintf("%q is not key=value", s)}
	}
	return parts[0], parts[1], nil
}

func load(i int, s string) (string, string, error) {
	key, value, err := parseSetting(i, s)
	if err != nil {
		return "", "", fmt.Errorf("load: %w", err)
	}
	return key, value, nil
}

func main() {
	var word string
	i := 0
	for {
		if _, err := fmt.Scan(&word); err != nil {
			break
		}
		i++
		key, value, err := load(i, word)
		if err != nil {
			fmt.Println("error:", err)
			var se *SettingError
			if errors.As(err, &se) {
				fmt.Println("  bad index:", se.Index)
			}
			continue
		}
		fmt.Println(key, "->", value)
	}
}
